# permission check enforced inside the MCP server, not the agent
TOOL_PERMISSIONS = {
    "search_emails": {"requires_approval": False},
    "read_thread":   {"requires_approval": False},
    "draft_reply":   {"requires_approval": False},
    "send_email":    {"requires_approval": True},
}

def can_execute(tool_name, approval_token=None):
    rule = TOOL_PERMISSIONS[tool_name]
    if rule["requires_approval"] and not approval_token:
        return False, "send_email needs a human approval token"
    return True, None

def search_emails(query, max_results=10):
    results = gmail_service.users().messages().list(
        userId="me",
        q=query,
        maxResults=max_results
    ).execute()

    messages = results.get("messages", [])
    summaries = []
    for msg in messages:
        full = gmail_service.users().messages().get(
            userId="me", id=msg["id"], format="metadata"
        ).execute()
        headers = {h["name"]: h["value"] for h in full["payload"]["headers"]}
        summaries.append({
            "id": msg["id"],
            "threadId": full["threadId"],
            "from": headers.get("From"),
            "subject": headers.get("Subject"),
            "snippet": full.get("snippet"),
        })
    return summaries

def draft_reply(thread_id, to_address, reply_text):
    mime_message = build_mime_reply(to_address, reply_text, thread_id)

    draft = gmail_service.users().drafts().create(
        userId="me",
        body={"message": {"raw": mime_message, "threadId": thread_id}}
    ).execute()

    return {
        "draft_id": draft["id"],
        "status": "pending_human_review",
        "note": "This draft has not been sent. It requires approval."
    }

function sendEmail({ draftId, approvedBy, approvalTimestamp }) {
  if (!approvedBy) {
    throw new Error("send_email blocked: missing human approval token");
  }

  auditLog.record({
    action: "send_email",
    draftId,
    approvedBy,
    approvalTimestamp,
  });

  return gmail.users.drafts.send({
    userId: "me",
    requestBody: { id: draftId },
  });
}
